"""One-page quick-start guide (PDF), generated by the app: Help > Save quick-start."""
from __future__ import annotations

from pathlib import Path

from reportlab.lib.colors import HexColor
from reportlab.lib.pagesizes import letter
from reportlab.pdfgen.canvas import Canvas

from .. import __version__
from .textfit import safe, wrap

SECTIONS = [
    ("Start", [
        "Open a sample: File > Open sample > Simple 90. Save your own work with Ctrl+S "
        "(.flareline.json).",
        "Every start shows the disclaimer: FlareLine is a design aid only.",
    ]),
    ("1 Tube spec  2 Ends", [
        "Pick size, material and wall. Chips show where each value comes from: green VERIFIED, "
        "purple USER INPUT, grey DEFAULT, red UNVERIFIED / MISSING.",
        "Choose 37° flare, plain or flareless for each end. End points sit at the flare; the "
        "end allowance is added to the cut length.",
    ]),
    ("3 Route & bends", [
        "Edit the bend table: XYZ (points, Z up, P0 = end 1), LRA (Y feed between tangent "
        "points, B rotation, C bend angle) or Legs (point to point). All three stay in sync.",
        "LRA 'Marks from P0' gives start and end of each bend for hand bending.",
        "Add leg: Ctrl+L. Undo / redo: Ctrl+Z / Ctrl+Y. Rotation display (CW/CCW, viewpoint) "
        "is set in step 3.",
    ]),
    ("4 Check", [
        "Red errors: the tube cannot be made (overlapping bends, bend past the end, CLR <= OD/2, "
        "self-interference). Amber warnings: a limit or a data value needs attention.",
        "Click any number, 2D dimension or warning: the Explain tab shows its formula and "
        "full-precision inputs.",
    ]),
    ("5 Drawing", [
        "Fill in the title block, notes and revisions, then File > Export drawing (Ctrl+E): "
        "PDF, DXF, PNG, CSV on ANSI A, B or D.",
        "Unless there are no errors and all data is verified, the drawing is watermarked NOT "
        "FOR FABRICATION. The PDF includes a calculation record for every number.",
        "Approved deviations (Tools) replace a data value for one project, with approval "
        "reference and approver; they are printed in the notes.",
    ]),
    ("Standards data", [
        "Tools > Standards & shop data (Ctrl+D). Enter values from your licensed standards, "
        "give a reason, then Mark row verified with standard, revision, table and date. "
        "Every change is logged. FlareLine ships with no standards values.",
    ]),
    ("Views and keys", [
        "3D: drag orbit, middle/Shift-drag pan, wheel zoom; F fit, 0 iso, 1 front, 2 top, "
        "3 right, M measure, S section. 2D: wheel zoom, double-click fit. F1: How-to panel.",
    ]),
]


def write_quickstart(path: Path | str) -> None:
    W, H = letter
    c = Canvas(str(path), pagesize=letter, invariant=1)
    c.setTitle("FlareLine quick start")
    c.setCreator(f"FlareLine {__version__}")
    m = 0.6 * 72
    y = H - m
    c.setFillColor(HexColor("#2563EB"))
    c.setFont("Helvetica-Bold", 20)
    c.drawString(m, y - 14, "FlareLine quick start")
    c.setFillColor(HexColor("#5B6470"))
    c.setFont("Helvetica", 9)
    c.drawRightString(W - m, y - 12, f"version {__version__}")
    y -= 34
    c.setFillColor(HexColor("#C62828"))
    c.setFont("Helvetica-Bold", 9)
    for ln in wrap("Design aid only. All geometry must be verified and approved per your "
                   "organization's engineering and quality process before fabrication.",
                   9 / 72, (W - 2 * m) / 72, bold=True):
        c.drawString(m, y, ln)
        y -= 12
    y -= 6
    for title, items in SECTIONS:
        c.setFillColor(HexColor("#1B1F24"))
        c.setFont("Helvetica-Bold", 11)
        c.drawString(m, y, safe(title))
        y -= 15
        c.setFont("Helvetica", 9.2)
        for item in items:
            lines = wrap(item, 9.2 / 72, (W - 2 * m - 14) / 72)
            c.drawString(m + 2, y, "•")
            for ln in lines:
                c.drawString(m + 14, y, ln)
                y -= 12
            y -= 2
        y -= 6
    c.setFillColor(HexColor("#5B6470"))
    c.setFont("Helvetica", 8)
    c.drawString(m, m - 10, "Full guide: docs/USER_GUIDE.md. FlareLine is fully offline: no "
                            "network calls, no telemetry.")
    c.showPage()
    c.save()
